item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure whether repeated testing occurred. Stability remains unestablished."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run establishes neither stability nor instability across runs."
        }
      ],
      "instrument_review": "MESA 14: No, repeated testing explicitly did not occur. This leaves score stability unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, variation across repeated runs was tested. Results support stability under the stated definition and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions occurred."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred, although the results fail the report's stability criterion. Testing and favourable findings are separate judgments."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not supply evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no findings about score stability."
        }
      ],
      "instrument_review": "MESA 14 remains Not sure. Installation guidance contributes to MESA 22 on reproducibility but does not establish that repeated evaluations occurred."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated grid puzzles under the reported conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 20 and 25: The narrow comparison fits the intended use and supplied evidence. A broader intelligence claim lacks supporting evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results support A's better performance on these grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "MESA 9 and 20: Coverage and evidence beyond grid puzzles are insufficient for the intended general-intelligence selection. The narrow result remains supported."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "The trial supplies no measured safety benefit; improved correctness alone does not establish one."
        }
      ],
      "instrument_review": "MESA 20: The later trial provides evidence beyond test scores for correctness in the studied workshop. MESA 16: The reported uncertainty interval supports that comparison. Safety and wider settings remain unestablished."
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was distinguished from explicit contradiction, and testing was distinguished from favourable results."
}
